136	// Files git marks vendored or generated (linguist-vendored / linguist-generated in
137	// .gitattributes) — third-party or machine-written content, not the project's own
138	// code. `buildContext` drops these from the default `ctx.files`, so every check that
139	// reasons about "the project's code" skips them for free: a suppression marker inside
140	// a recorded fixture, a placement "violation" in a generated artifact, and a dangling
141	// link in a vendored doc are none of them the project's decision. `git check-attr`
142	// honors .gitattributes patterns/precedence natively (paths on stdin so a large repo
143	// can't overflow the arg list). The unfiltered set stays on `ctx.allFiles` for the one
144	// check that reasons *about* generated files (generated-merge-driver).
145	function vendoredSet(root, files) {
146	  const set = new Set();
147	  if (!files.length) return set;
148	  const out = sh(root, 'git', ['check-attr', '--stdin', 'linguist-vendored', 'linguist-generated'],
149	    { allowFail: true, input: files.join('\n') + '\n' });
150	  for (const line of (out || '').split('\n')) {
151	    const m = /^(.*): (?:linguist-vendored|linguist-generated): (.*)$/.exec(line);
152	    if (m && m[2] === 'set') set.add(m[1]);
153	  }
154	  return set;
155	}
