287	  const path = settingsPath(root);
288	  const empty = { packs: [], packEntries: [], rules: {}, accept: [], sharedConstants: [], packConfig: {}, taskScheduler: null, engineVersion: null, packVersions: {}, dailyClaudiniteUpdatesRequirePrReview: false, raw: null, errors: [] };
289	  if (!existsSync(path)) return empty;
290	
291	  let raw;
292	  try {
293	    raw = JSON.parse(readFileSync(path, 'utf8'));
294	  } catch (e) {
295	    return { ...empty, errors: [{ what: `${SETTINGS_FILE} is not valid JSON: ${e.message}`, fix: 'fix the JSON syntax' }] };
296	  }
297	  if (raw === null || typeof raw !== 'object' || Array.isArray(raw)) {
298	    return { ...empty, errors: [{ what: `${SETTINGS_FILE} must be a JSON object`, fix: 'wrap the settings in an object: { "packs": [ ... ] }' }] };
299	  }
