301	  const errors = [];
302	  for (const key of Object.keys(raw)) {
303	    if (!KNOWN_CONFIG_KEYS.includes(key)) {
304	      errors.push({ what: `unknown setting "${key}"`, fix: `remove it or fix the name — valid settings: ${CONFIG_KEYS.join(', ')}` });
305	    }
306	  }
307	
308	  // --- packs: each entry a pack id or { id, config?, rules?, accept?, via? } ---
309	  const packs = [];
310	  const packEntries = [];
311	  for (const entry of Array.isArray(raw.packs) ? raw.packs : []) {
312	    if (typeof entry === 'string') {
313	      packs.push(packEntryId(entry));
314	      packEntries.push({ id: packEntryId(entry) });
315	      continue;
316	    }
317	    if (entry === null || typeof entry !== 'object' || Array.isArray(entry)) {
318	      errors.push({ what: `packs entry ${JSON.stringify(entry)} is neither a pack id nor an entry object`, fix: 'declare a pack as "name" or { "id": "name", ... }' });
