333	    if (entry.version !== undefined) {
334	      if (isVersion(entry.version)) normalized.version = entry.version;
335	      else badShape('version', 'the installed pack version — date-anchored <day>.<n>');
336	    }
337	    if (entry.config !== undefined) {
338	      if (entry.config !== null && typeof entry.config === 'object' && !Array.isArray(entry.config)) normalized.config = entry.config;
339	      else badShape('config', 'an object of the pack\'s parameters');
340	    }
341	    if (entry.answers !== undefined) {
