=========== packs/basics/worldRules/claude-md-length.mjs
     1	// What the project's instruction file costs a session is what it BRINGS, not what it
     2	// holds: an `@path` line in CLAUDE.md pulls that file, and everything it imports in
     3	// turn, into every window the repo ever opens, in full. So the budget is over the
     4	// resolved tree, and the unit is tokens, because a context window is what the cost
     5	// lands in and lines say nothing about it.
     6	//
     7	// Coded rather than declared: the declaration language matches lines within one file,
     8	// and this assertion is a sum over a set of files that only reading the first one
     9	// names. The check kept its id when it moved off `maxLines`: `usage.GENERATED.json`
    10	// stores its finding counts under that name, and a rename would read the series as
    11	// ending rather than continuing.
    12	import { dirname, join, normalize } from 'node:path';
    13	import { finding } from '../../../engine/checks/helpers/findings.mjs';
    14	import { countWords, estimateTokens } from '../../../engine/pack_loader/token-estimate.mjs';
    15	
    16	// Only the root file: the harness loads that one, and a CLAUDE.md under a fixture or
    17	// an example directory costs a session nothing.
    18	const ROOT = 'CLAUDE.md';
    19	
    20	// One import per line, the form the harness resolves: `@` at the start of the line,
    21	// then a path, relative to the file the line is in.
    22	const IMPORT = /^@(\S+)\s*$/;
    23	
    24	// Chosen as a ceiling rather than a target. The point is to notice the tree growing
    25	// past what a session can carry alongside the work, not to demand the corpus shrink
    26	// today. A repo whose packs legitimately cost more than this says so by raising it
    27	// here, in one place, deliberately.
    28	const BUDGET_TOKENS = 20000;
    29	
    30	// The tree under the root file, each file counted once. A cycle is ordinary rather
    31	// than exceptional (two rule files that point at each other still load once each),
    32	// so the seen set is what bounds the walk, not a depth limit.
    33	function importedTree(ctx, entry) {
    34	  const seen = new Set();
    35	  const queue = [entry];
    36	  let words = 0;
    37	  while (queue.length) {
    38	    const path = queue.shift();
    39	    if (seen.has(path)) continue;
    40	    seen.add(path);
    41	    const text = ctx.read(path);
    42	    // An import resolving to nothing is not this check's finding to make: it costs a
    43	    // session no tokens, which is the only question being asked here.
    44	    if (text === null) continue;
    45	    words += countWords(text);
    46	    for (const line of text.split('\n')) {
    47	      const m = IMPORT.exec(line);
    48	      if (m) queue.push(normalize(join(dirname(path), m[1])));
    49	    }
    50	  }
    51	  return words;
    52	}
    53	
    54	const rule = {
    55	  id: 'claude-md-length',
    56	  severity: 'advisory',
    57	  description: 'Everything CLAUDE.md pulls into the window, counted together, stays under the context budget',
    58	  why: 'every session in the repo pays for the whole import tree before it reads a line of the work, and the file that names it is often one line long',
    59	
    60	  run(ctx) {
    61	    if (!ctx.files.includes(ROOT)) return [];
    62	    const tokens = estimateTokens(importedTree(ctx, ROOT));
    63	    if (tokens <= BUDGET_TOKENS) return [];
    64	    return [finding(rule, {
    65	      file: ROOT,
    66	      line: 1,
    67	      what: `CLAUDE.md and what it imports come to ${tokens.toLocaleString('en-US')} tokens (budget ${BUDGET_TOKENS.toLocaleString('en-US')})`,
    68	      fix: 'cut the rules a check now enforces, move a multi-step procedure into a skill that loads on demand, and drop a rule another pack already carries; every one of them is paid for by every session, whether or not it applies',
    69	    })];
    70	  },
    71	};
    72	
    73	export default rule;
=========== packs/basics/worldRules/declared-check-since.mjs
     1	// A NAMESPACE import for the same reason the sibling spec-keys rule takes one: the
     2	// pack and the engine deliver on separate cycles, so this file can sit beside an
     3	// engine whose findings helper predates `graceUntil`, and a named import of an
     4	// absent export is a link-time SyntaxError that faults the whole pack.
     5	import * as findings from '../../../engine/checks/helpers/findings.mjs';
     6	
     7	// An `action` check is re-judged over the WHOLE session transcript at Stop, so a
     8	// blocking one that lands mid-session convicts calls the session made before it
     9	// existed — and a past tool call has no clearing move, so that finding blocks every
    10	// Stop for the rest of the session. `since` is the corpus's answer: it buys the new
    11	// check a grace window in which it reports without blocking. Absence means "mature,
    12	// never newborn" (findings.mjs), which is right for the standing corpus and wrong
    13	// for every check added from here on — this rule is what makes the dating happen at
    14	// the moment the declaration is written.
    15	//
    16	// Coded rather than declared: the assertion is over one spec object's shape — two
    17	// keys present, a third absent — which the declaration language's line matching
    18	// cannot express without reading the neighbouring lines it has no access to.
    19	const DECLARED = /(^|\/)declared-checks\.json$/;
    20	
    21	// Whether a declared `since` actually buys grace, asked of the engine that grants
    22	// it rather than restated here. An engine without the export cannot grant grace to
    23	// anyone, so any date reads as good and the rule falls back to demanding one.
    24	function datesTheCheck(since) {
    25	  if (typeof findings.graceUntil === 'function') return findings.graceUntil(since) !== null;
    26	  return typeof since === 'string' && since.trim() !== '';
    27	}
    28	
    29	const rule = {
    30	  id: 'declared-check-since',
    31	  severity: 'blocking',
    32	  // Dated on its own terms: a member holding an undated blocking action check reads
    33	  // this the moment it converges, and the remedy is theirs to write.
    34	  since: '2026-09-06',
    35	  description: 'Every blocking action-scope check carries a `since` date the grace window can read',
    36	  why: 'a blocking action check with no usable `since` convicts the tool calls a session made before the check existed, and a past call has no clearing move',
    37	
    38	  run(ctx) {
    39	    const out = [];
    40	    for (const file of ctx.files.filter((f) => DECLARED.test(f))) {
    41	      const text = ctx.read(file);
    42	      if (text === null) continue;
    43	      let specs;
    44	      try { specs = JSON.parse(text); } catch { continue; } // unparsable is the loader's finding
    45	      if (!Array.isArray(specs)) continue;
    46	      for (const spec of specs) {
    47	        if (!spec || typeof spec !== 'object' || typeof spec.id !== 'string') continue;
    48	        if (spec.scope !== 'action' || spec.severity !== 'blocking') continue;
    49	        if (datesTheCheck(spec.since)) continue;
    50	        const anchor = text.slice(0, text.indexOf(`"${spec.id}"`)).split('\n').length;
    51	        out.push(findings.finding(rule, {
    52	          file,
    53	          line: anchor,
    54	          what: spec.since === undefined
    55	            ? `"${spec.id}" blocks on tool calls and carries no "since"`
    56	            : `"${spec.id}" blocks on tool calls and its "since" of "${String(spec.since).slice(0, 30)}" is not a YYYY-MM-DD date`,
    57	          fix: 'add "since": the YYYY-MM-DD date this check lands, so its first two weeks report without blocking the sessions that predate it',
    58	        }));
    59	      }
    60	    }
    61	    return out;
    62	  },
    63	};
    64	
    65	export default rule;
=========== packs/claudinite-growth/worldRules/provenance-integrity.mjs
     1	import { finding } from '../../../engine/checks/helpers/findings.mjs';
     2	// A namespace import, guarded below: the pack and engine lanes deliver on separate
     3	// cadences, and a member whose engine predates the helper must load this pack rather
     4	// than fault on a missing named export.
     5	import * as provenance from '../../../engine/checks/helpers/provenance.mjs';
     6	
     7	// THE WORLD HALF of the provenance convention (the provenance design, #2136): every
     8	// carrier of every pack under either root names a live provenance file, every
     9	// provenance file parses, and a file with entries opens with born and carries
    10	// Mechanism where its kind demands one. A member's local packs and a canon's shelf are
    11	// judged alike; the mount is never scanned (ctx.files excludes it).
    12	//
    13	// AGGREGATED PER FILE where a fault repeats: a RULES.md with twenty unmarked rules is
    14	// one finding naming the count and the first, not twenty - the fix is one command over
    15	// the pack either way. A dangling marker, an unnamed file, a bodyless skill and a
    16	// grammar fault are each their own finding, because each has its own line.
    17	//
    18	// TWO ADVISORY BRANCHES inside a blocking rule: an EMPTY file is pending history, the
    19	// backfill's worklist and not a defect; a pack-root references.md is the retired
    20	// convention still in place, tolerated at advisory through the conversion window.
    21	//
    22	// A GUIDELINES SKILL'S BULLET carries a marker only where its history has a file of its
    23	// own; unmarked, it is the skill's, covered by the file the skill names, so the unmarked
    24	// finding names RULES.md rules alone. Two carriers may name one file while their history
    25	// is one (the owner's call, 2026-09-20).
    26	//
    27	// RELEVANCE-FIRST: inert in a repo that carries no pack under either root.
    28	const PACK = 'claudinite-growth';
    29	const toolPath = (ctx) => (ctx.exists(`packs/${PACK}/provenance.mjs`) ? `packs/${PACK}/provenance.mjs` : `.claudinite/shared/packs/${PACK}/provenance.mjs`);
    30	const packId = (dir) => dir.slice(dir.lastIndexOf('/') + 1);
    31	
    32	const rule = {
    33	  id: 'provenance-integrity',
    34	  severity: 'blocking',
    35	  since: '2026-09-20',
    36	  doc: 'packs/claudinite-growth/skills/changing-pack-elements/SKILL.md',
    37	  description: 'Every pack carrier names a live provenance file, and every provenance file parses',
    38	  why: 'a rule with no file has no id an override can name and no log a review can reaffirm it against, and a file nothing names is history of an element that is gone',
    39	
    40	  run(ctx) {
    41	    if (typeof provenance.auditPack !== 'function') return []; // an engine that predates the helper
    42	    const { auditPack, packDirsIn, fileOfId, PROVENANCE_DIR } = provenance;
    43	    const packs = packDirsIn(ctx.files);
    44	    if (!packs.length) return [];
    45	    const io = { exists: (p) => ctx.exists(p), read: (p) => ctx.read(p), listDir: (p) => listFrom(ctx.files, p) };
    46	    const tool = toolPath(ctx);
    47	    const out = [];
    48	    for (const dir of packs) {
    49	      const a = auditPack(dir, io);
    50	      const id = packId(dir);
    51	      const mark = `run \`node ${tool} mark ${id}\` and refine the proposed slugs before landing`;
    52	      const byFile = new Map();
    53	      for (const u of a.unmarked) { if (!byFile.has(u.file)) byFile.set(u.file, []); byFile.get(u.file).push(u); }
    54	      for (const [file, list] of byFile) {
    55	        out.push(finding(rule, {
    56	          file, line: list[0].line,
    57	          what: `${list.length} rule${list.length === 1 ? '' : 's'} end${list.length === 1 ? 's' : ''} with no marker naming a provenance file (first: "${list[0].trigger}")`,
    58	          fix: mark,
    59	        }));
    60	      }
    61	      for (const d of a.dangling) {
    62	        out.push(finding(rule, {
    63	          file: d.file, line: d.line,
    64	          what: `${d.carrier} names ${dir}/${PROVENANCE_DIR}/${fileOfId(d.id)}, which is ${d.retired ? 'retired - its last entry retired the element' : 'not a file'}`,
    65	          fix: d.retired
    66	            ? 'a retired element carries no live carrier: remove the carrier, or give the element a new file and a born entry'
    67	            : `create the file the carrier names (\`node ${tool} mark ${id}\` creates every missing one), or fix the marker to the file it meant`,
    68	        }));
    69	      }
    70	      for (const u of a.unnamed) {
    71	        out.push(finding(rule, {
    72	          file: u.file,
    73	          what: `is live, and no carrier of ${dir} names ${fileOfId(u.id)}`,
    74	          fix: 'append a retired entry if the element is gone, or restore the marker or id that named it',
    75	        }));
    76	      }
    77	      for (const n of a.noBody) {
    78	        out.push(finding(rule, {
    79	          file: n.file,
    80	          what: `skill ${n.skill} declares no body`,
    81	          fix: `add \`body: workflow\` or \`body: guidelines\` under its frontmatter metadata (\`node ${tool} mark ${id}\` proposes one from the shape)`,
    82	        }));
    83	      }
    84	      for (const m of a.markerInWorkflow) {
    85	        out.push(finding(rule, {
    86	          file: m.file, line: m.line,
    87	          what: `"${m.trigger}" ends with the marker (${m.slug}) inside a skill whose body is a workflow`,
    88	          fix: 'a workflow\'s steps owe their entries to the skill\'s own file: drop the marker, or declare the skill body: guidelines',
    89	        }));
    90	      }
    91	      for (const e of [...a.parseErrors, ...a.entryFaults]) {
    92	        out.push(finding(rule, {
    93	          file: e.file, line: e.line,
    94	          what: e.what,
    95	          fix: 'write the entry in the file grammar - `## <YYYY-MM-DD> · <kind> · <one line>` and `- **Field:** …` lines, appended in date order, born first, Mechanism on every mechanism-bearing kind - through `append`, which validates it',
    96	        }));
    97	      }
    98	      // Pending history is one line per pack, not one per file: it is the backfill's
    99	      // worklist, and a worklist is read as a count.
   100	      if (a.empty.length) {
   101	        const ids = a.empty.map((e) => fileOfId(e.id)).sort();
   102	        out.push(finding(rule, {
   103	          file: `${dir}/${PROVENANCE_DIR}`, severity: 'advisory',
   104	          what: `${ids.length} provenance file${ids.length === 1 ? ' is' : 's are'} empty - elements whose history is not written yet (${ids.slice(0, 3).join(', ')}${ids.length > 3 ? ', …' : ''})`,
   105	          fix: 'the backfill fills them from each carrier\'s history (the backfilling-provenance skill), which says how a run is sized into pull requests; nothing else is owed',
