2	import assert from 'node:assert/strict';
3	import { execFileSync } from 'node:child_process';
4	import { join, dirname } from 'node:path';
5	import { fileURLToPath } from 'node:url';
6	
7	// The engine lane and the pack lane deliver in SEPARATE PRs on separate cycles, and
8	// pack delivery is version-gated per pack — so every member spends a window holding
9	// the new engine beside an old pack. A `packs/**` file importing an `engine/**`
10	// module is therefore a stale caller of an instantly-current engine, and an engine
11	// module it names may not simply vanish.
12	//
13	// It vanished once (#1004). `packs/acme-pack-b/task-declaration-shape.mjs` imported
14	// the engine's own `slots.mjs`, #974 renamed that to `calendar.mjs`, and the next
15	// member to converge got a mount whose `core` pack would not load — which fails the
16	// self-test, which makes the converge refuse to land AT ALL, so the member could not
17	// even receive the pack version that would have fixed it.
18	//
19	// QUANTIFIED OVER HISTORY, NOT A LIST. Which symbols matter is a fact about the pack
20	// versions members are actually carrying, and members carry old ones — so the
21	// question is asked of every version of every pack file that ever REACHED the trunk,
22	// not of HEAD and not of a list someone remembers to acme-task-c.
23	//
24	// The trunk, not `--all`: a member's pack version came from a release cut from the
25	// default branch, so an import that only ever existed on an unmerged branch is not a
26	// fielded import. Scanning every ref instead fires on whatever else is in flight —
27	// which is exactly what it did the first time this test ran.
28	
29	const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
30	const git = (...args) => execFileSync('git', args, { cwd: ROOT, encoding: 'utf8', maxBuffer: 64e6 });
31	const gitOk = (...args) => { try { git(...args); return true; } catch { return false; } };
32	
33	// The trunk as this checkout can name it. CI checks out the PR head with full
34	// history and `origin/main` present; a local branch has it too. `HEAD` is the
35	// fallback rather than a hard failure, since a checkout without the remote ref is a
36	// worse-scoped run, not a broken one.
37	const TRUNK = gitOk('rev-parse', '--verify', 'origin/main') ? 'origin/main' : 'HEAD';
38	
39	// Every `import { … } from '…/engine/<path>'` that any version of any packs/** file
