      SWITCH.lastIndex = 0;
      for (let m = SWITCH.exec(src); m; m = SWITCH.exec(src)) {
        const parenAt = m.index + m[0].length - 1;
        const head = balanced(src, parenAt);
        if (head === null) continue;
        const braceAt = src.indexOf('{', parenAt + head.length);
