31	//      the single false alarm a naive "no `default` in this file" grep makes most.
32	//
33	// Comments are stripped first, so the error names named in the paragraphs above
34	// cannot fire the rule on this very file.
35	
36	// SpeechRecognitionErrorCode, as specified. Deliberately the SPEC list and not a
37	// superset: these are the names a mapping is expected to enumerate, and seeing two
38	// of them as case labels is what identifies a switch as a speech-error mapping.
39	// The rule's whole point is the names NOT on this list, so guessing at extensions
40	// here would be self-defeating.
41	const ERROR_NAMES = [
42	  'no-speech',
43	  'aborted',
44	  'audio-capture',
45	  'network',
46	  'not-allowed',
47	  'service-not-allowed',
48	  'bad-grammar',
49	  'language-not-supported',
50	];
51	
52	const SWITCH = /\bswitch\s*\(/g;
53	const CASE = /^case\s+(['"`])([^'"`]*)\1\s*:/;
54	const DEFAULT = /^default\s*:/;
55	
56	/**
57	 * The case labels and `default:` presence at a switch body's own brace depth.
58	 * `body` is the balanced `{…}` run including both braces. Depth-aware so a nested
59	 * switch inside one arm contributes neither its labels nor its default; string and
60	 * template literals are skipped so a colon inside `"a:b"` can't read as syntax.
61	 */
62	function arms(body) {
63	  const labels = new Set();
64	  let hasDefault = false;
65	  let depth = 0;
66	  for (let i = 1; i < body.length - 1; i++) {
67	    const c = body[i];
68	    if (c === '"' || c === "'" || c === '`') {
69	      const quote = c;
70	      for (i += 1; i < body.length; i++) {
71	        if (body[i] === '\\') { i += 1; continue; }
72	        if (body[i] === quote) break;
73	      }
74	      continue;
75	    }
76	    if (c === '{' || c === '[' || c === '(') { depth += 1; continue; }
77	    if (c === '}' || c === ']' || c === ')') { depth -= 1; continue; }
78	    if (depth !== 0 || /[\w$]/.test(body[i - 1])) continue;
79	    const rest = body.slice(i);
80	    const label = CASE.exec(rest);
81	    if (label) {
82	      labels.add(label[2]);
83	      i += label[0].length - 1;
84	      continue;
85	    }
86	    if (DEFAULT.test(rest)) hasDefault = true;
87	  }
88	  return { labels, hasDefault };
89	}
90	
91	const rule = {
92	  id: 'stt-error-map-has-default',
93	  severity: 'blocking',
94	  description: 'A speech-recognition error mapping is total — every name maps to a kind',
95	  doc: 'packs/web-speech/RULES.md',
96	  why: 'the Web Speech error-name set is open — browsers extend it — so a mapping switch with no catch-all returns undefined for a name it does not enumerate; the dialog policy then compares undefined against every kind it knows, takes its do-nothing arm, and the session dies without throwing, logging, or changing the UI',
97	
98	  run({ sources }) {
99	    const out = [];
100	    for (const source of sources(isSource)) {
101	      if (ERROR_NAMES.filter((name) => source.text.includes(name)).length < 2) continue;
102	      const { file, code: src, line } = source;
103	      SWITCH.lastIndex = 0;
104	      for (let m = SWITCH.exec(src); m; m = SWITCH.exec(src)) {
105	        const parenAt = m.index + m[0].length - 1;
106	        const head = balanced(src, parenAt);
107	        if (head === null) continue;
108	        const braceAt = src.indexOf('{', parenAt + head.length);
109	        if (braceAt === -1 || src.slice(parenAt + head.length, braceAt).trim() !== '') continue;
110	        const body = balanced(src, braceAt);
111	        if (body === null) continue;
112	
113	        const { labels, hasDefault } = arms(body);
114	        const known = ERROR_NAMES.filter((name) => labels.has(name));
115	        if (known.length < 2) continue; // not a speech-error mapping
116	        if (!/\breturn\b/.test(body)) continue; // dispatch, not a mapping
117	        if (hasDefault) continue;
118	        // A `return`/`throw` straight after the switch is the catch-all, and the
119	        // mapping is total without a `default:` arm.
120	        if (/^(?:return|throw)\b/.test(src.slice(braceAt + body.length).replace(/^[\s;]*/, ''))) continue;
121	
122	        out.push(finding(rule, {
123	          file,
124	          line: line(m.index),
125	          what: `a switch mapping Web Speech recognition error names (${known.join(', ')}) has no default arm, so any other name maps to undefined`,
126	          fix: 'give the switch a `default:` arm returning your catch-all kind (or `return` that kind straight after the switch) — the taxonomy the dialog policy reasons over has to name "some other error" explicitly, so a name this browser build invented degrades to a handled kind instead of silently becoming undefined',
127	        }));
128	      }
129	    }
130	    return out;
131	  },
132	};
133	
134	export default rule;

